using QuantForge.Core;namespace QuantForge.Core.ArchitectureTests;public sealed class ProgramReadinessReportFileStoreTests{[Fact]public void Persisted_report_remains_simulation_only(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));try{var path=Path.Combine(root,"readiness.json");var value=new ProgramReadinessReport("0.30.79","3079",true,false,false,false,true,false,new[]{"native"});var store=new ProgramReadinessReportFileStore(path);store.Save(value);Assert.Equal(value,store.Load());}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}}
